pub fn strip_fragment(input: &str) -> &str {
    match input.find('#') {
        Some(position) => &input[..position],
        None => input,
    }
}

pub fn split_scheme(input: &str) -> Option<(&str, &str)> {
    input
        .find("://")
        .map(|position| (&input[..position], &input[position + 3..]))
}

pub fn split_authority_and_suffix(input: &str) -> (&str, &str) {
    match find_first_delimiter(input, b'/', b'?') {
        Some(position) => (&input[..position], &input[position..]),
        None => (input, ""),
    }
}

pub fn split_path_and_query(input: &str) -> (String, String) {
    match input.find('?') {
        Some(position) => (input[..position].to_string(), input[position + 1..].to_string()),
        None => (input.to_string(), String::new()),
    }
}

pub fn split_host_and_port(input: &str) -> Option<(&str, i32)> {
    let position = input.find(':')?;
    let host = &input[..position];
    let port = parse_port_prefix(&input[position + 1..]);
    Some((host, port))
}

fn find_first_delimiter(input: &str, left: u8, right: u8) -> Option<usize> {
    input
        .bytes()
        .position(|byte| byte == left || byte == right)
}

fn parse_port_prefix(input: &str) -> i32 {
    let digits = input
        .as_bytes()
        .iter()
        .take_while(|byte| byte.is_ascii_digit())
        .count();

    if digits == 0 {
        return -1;
    }

    match input[..digits].parse::<u32>() {
        Ok(port) if port <= 65_535 => port as i32,
        _ => -1,
    }
}

