mod authority;
mod split;

use self::authority::parse_authority;
use self::split::{split_authority_and_suffix, split_path_and_query, split_scheme, strip_fragment};

pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
}

impl URL {
    pub fn new(input: &str) -> Self {
        let without_fragment = strip_fragment(input);

        if let Some((scheme, remainder)) = split_scheme(without_fragment) {
            let (authority, suffix) = split_authority_and_suffix(remainder);
            let (host, port) = parse_authority(authority);
            let (path, query) = split_path_and_query(suffix);

            Self {
                scheme: scheme.to_string(),
                host,
                port,
                path,
                query,
            }
        } else {
            let (path, query) = split_path_and_query(without_fragment);

            Self {
                scheme: String::new(),
                host: String::new(),
                port: -1,
                path,
                query,
            }
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }
}

#[cfg(test)]
mod tests {
    use super::URL;

    #[test]
    fn parses_basic_urls() {
        let parser = URL::new("http://example.com");
        assert_eq!(parser.scheme(), "http");
        assert_eq!(parser.host(), "example.com");
        assert_eq!(parser.port(), -1);
        assert_eq!(parser.path(), "");
        assert_eq!(parser.query(), "");
    }

    #[test]
    fn parses_path_and_query() {
        let parser = URL::new("http://example.com/path?x=1");
        assert_eq!(parser.scheme(), "http");
        assert_eq!(parser.host(), "example.com");
        assert_eq!(parser.port(), -1);
        assert_eq!(parser.path(), "/path");
        assert_eq!(parser.query(), "x=1");
    }

    #[test]
    fn strips_userinfo_and_fragment() {
        let parser = URL::new("http://user:pass@example.com:80/path?query=1#frag");
        assert_eq!(parser.scheme(), "http");
        assert_eq!(parser.host(), "example.com");
        assert_eq!(parser.port(), 80);
        assert_eq!(parser.path(), "/path");
        assert_eq!(parser.query(), "query=1");
    }

    #[test]
    fn treats_non_scheme_inputs_as_paths() {
        let parser = URL::new("example.com?x=1");
        assert_eq!(parser.scheme(), "");
        assert_eq!(parser.host(), "");
        assert_eq!(parser.port(), -1);
        assert_eq!(parser.path(), "example.com");
        assert_eq!(parser.query(), "x=1");
    }

    #[test]
    fn parses_only_numeric_port_prefix_in_range() {
        let parser = URL::new("http://example.com:12abc");
        assert_eq!(parser.port(), 12);

        let parser = URL::new("http://example.com:65536");
        assert_eq!(parser.port(), -1);
    }
}

